const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const campusStore=CampusStorage.open(localStorage);let state=campusStore.load();let editing=null;
$('month').value=campusStore.period()||new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date());
function save(){campusStore.save(state,$('month').value)}function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000)}
function ruleBy(id){return RULES.find(x=>x.id===id)}
function calculate(e){const scopeRule=ruleBy(e.rule);if(/workshop|招生讲座/i.test([scopeRule?.group,scopeRule?.item,e.raw?.type].join(' ')))return {amount:0,status:'排除：Workshop及招生讲座暂不纳入绩效'};if(e.excludedReason)return {amount:0,status:'排除：'+e.excludedReason};const signingRule=ruleBy(e.rule);if(e.sourceKind==='signup'||/辅助签约/.test(e.raw?.type||'')||(/辅助签约/.test(signingRule?.item||'')||(signingRule?.group||'').includes('签约'))){const payment=PayrollMatch.paymentStatus(e.fullPaid??e.raw?.fullPaid);if(payment==='unpaid')return {amount:0,status:'排除：未全款，辅助签约不予发放'};if(payment!=='paid')return {amount:0,status:'待确认：需确认是否已全款'};if(/[/／、,，;；&＆]/.test(e.teacher))return {amount:0,status:'待确认：多位试听签约老师，需确认领取人及分配金额'}}if(e.version==='老汉艺版本'&&(e.sourceKind==='signup'||/辅助签约/.test(signingRule?.item||''))){const result=PayrollMatch.oldSignup(e.raw||{package:e.enrolledCourse,signupHours:e.signupHours,signupProjects:e.signupProjects});if(result.excluded)return {amount:0,status:'排除：'+result.excluded};if(result.issue)return {amount:0,status:'待确认：'+result.issue};if(e.rule&&e.rule!==result.rule)return {amount:0,status:'待确认：所选规则与报名套餐数量不一致'}}if(e.importIssue)return {amount:0,status:'待确认：'+e.importIssue};if(e.version==="老汉艺版本"){const oldRule=ruleBy(e.rule);if(["old-hanyi-project","old-hanyi-base"].includes(e.rule))return {amount:0,status:"排除：老汉艺版本无"+(e.rule==="old-hanyi-project"?"项目":"基础课")+"绩效"};if(oldRule&&oldRule.version!==e.version)return {amount:0,status:"待确认：老汉艺版本不能套用其他版本标准"}}if(e.excludedReason)return {amount:0,status:'排除：'+e.excludedReason};if(e.importIssue)return {amount:0,status:'待确认：'+e.importIssue};const r=ruleBy(e.rule);if(!r)return {amount:0,status:'待确认：规则缺失'};if(e.nature!=='全职')return {amount:0,status:'排除：非全职'};if(e.condition==='no')return {amount:0,status:'排除：条件不符'};if(e.condition!=='yes')return {amount:0,status:'待确认：适用条件'};if(!Number.isFinite(e.ratio)||e.ratio<0||e.ratio>1)return {amount:0,status:'待确认：结算比例应在0到1之间'};if(e.ratio!==1&&(r.unit!=='项目'||r.group.includes('签约')||r.group==='竞赛奖励'))return {amount:0,status:'待确认：特殊结算比例仅适用项目结算'};let rate=r.rate,n=e.qty*rate;if(r.item.startsWith('成衣转介绍')){rate=e.qty<=6500?.05:e.qty<=10000?.08:.1;n=e.qty*rate}if(r.item==='自产转介绍')n=Math.max(0,Math.min(e.qty*.03,3000)-e.paid);n*=e.ratio;if((/辅助签约/.test(r.item||'')||(r.group||'').includes('签约'))&&e.signupShareCount>1){const totalCents=Math.round(n*100),count=e.signupShareCount,index=e.signupTeacherIndex||0;n=(Math.floor(totalCents/count)+(index<totalCents%count?1:0))/100}if(e.override!==null){if(!e.reason.trim())return {amount:0,status:'待确认：缺少调整原因'};n=e.override}if(!Number.isFinite(n)||n<0)return {amount:0,status:'待确认：金额无效'};return {amount:Math.round((n+Number.EPSILON)*100)/100,status:'可结算',rate}}
function monthEntries(){return state.entries.filter(e=>e.month===$('month').value)}
function populate(){const old=$('rule').value;$('rule').innerHTML='<option value="">请选择产品、绩效项目及套餐</option>'+RULES.filter(r=>r.version===$('version').value).map(r=>`<option value="${r.id}">${esc(r.group+' · '+r.item+' · '+r.tier+' ｜ '+r.rate+'元/'+r.unit)}</option>`).join('');if(ruleBy(old)?.version===$('version').value)$('rule').value=old;$('rule').required=true;estimate()}
function formEntry(){const previous=editing?state.entries.find(e=>e.id===editing):{};const selection=typeof StaffVersionPolicy!=='undefined'?StaffVersionPolicy.resolve($('teacher').value.trim(),$('studentSignDate').value,state.staff,state.staffRules||{}):{configured:false};const policyIssue=selection.configured?(selection.issue||($('version').value!==selection.version?'所选版本与签约日期规则不一致，请核对':'')):'';return {...previous,signDate:$('studentSignDate').value,versionReason:selection.reason||'',raw:previous?.raw?{...previous.raw,signDate:$('studentSignDate').value}:undefined,importIssue:policyIssue,excludedReason:'',manualResolved:!!editing,id:editing||crypto.randomUUID(),month:$('month').value,teacher:$('teacher').value.trim(),student:$('student').value.trim(),version:$('version').value,nature:$('nature').value,rule:$('rule').value,qty:Number($('qty').value),ratio:Number($('ratio').value),project:$('project').value.trim(),fullPaid:$('fullPaid').value,signupHours:$('signupHours').value,signupProjects:$('signupProjects').value,advisor:$('advisor').value.trim(),trialDate:$('trialDate').value,enrolledCourse:$('enrolledCourse').value.trim(),paid:Number($('paid').value),override:$('override').value===''?null:Number($('override').value),reason:$('reason').value,condition:$('condition').value,note:$('note').value}}
function estimate(){const e=formEntry(),r=ruleBy(e.rule);$('estimate').textContent=r?'预计金额 ¥'+money(calculate(e).amount)+(calculate(e).status==='可结算'?'':' · '+calculate(e).status):'';$('rulenote').textContent=r?[r.note,'排版需核实未上过1v1技法老师排版课（按适用制度）；软件课需核实授课人；BTEC与作品集重合内容不重复结算。'].filter(Boolean).join(' '):''}
function reset(){editing=null;$('entryform').reset();$('formtitle').textContent='手动补录';populate()}
function names(){return [...new Set([...Object.keys(state.staff),...monthEntries().filter(e=>e.nature==='全职').map(e=>e.teacher)])].sort()}
function salaryData(){return names().map(name=>{let s=state.salary[$('month').value+'|'+name]||{base:0,allowance:0,deduct:0};let perf=monthEntries().filter(e=>e.teacher===name).reduce((a,e)=>a+calculate(e).amount,0);let versions=[...new Set(monthEntries().filter(e=>e.teacher===name&&e.nature==='全职').map(e=>e.version))];return {name,version:versions.join(' / ')||state.staff[name]||'常规版',...s,perf,total:s.base+perf+s.allowance-s.deduct}})}
function render(){let entries=monthEntries(),results=entries.map(calculate);$('total').textContent='¥'+money(results.reduce((a,x)=>a+x.amount,0));$('people').textContent=new Set(entries.filter((e,i)=>results[i].status==='可结算').map(e=>e.teacher)).size;$('valid').textContent=results.filter(x=>x.status==='可结算').length;$('pending').textContent=results.filter(x=>x.status.startsWith('待')).length+' / '+results.filter(x=>x.status.startsWith('排')).length;
 $('teachers').innerHTML=Object.keys(state.staff).map(n=>`<option value="${esc(n)}">`).join('');$('stafflist').innerHTML='<table><tr><th>员工</th><th>版本</th></tr>'+Object.entries(state.staff).map(([n,v])=>`<tr><td>${esc(n)}</td><td>${esc(v)}</td></tr>`).join('')+'</table>';
 $('salaryrows').innerHTML=salaryData().map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.version)}</td>${['base'].map(k=>salaryInput(s,k)).join('')}<td>¥${money(s.perf)}</td>${['allowance','deduct'].map(k=>salaryInput(s,k)).join('')}<td>¥${money(s.total)}</td></tr>`).join('')||'<tr><td colspan="7">添加员工或绩效记录后显示工资汇总。</td></tr>';save()}
function salaryInput(s,k){return `<td><input style="width:115px" type="number" min="0" step="0.01" data-person="${esc(s.name)}" data-salary="${k}" value="${s[k]}"></td>`}
function download(text,name,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csv(rows,name){download('\ufeff'+rows.map(row=>row.map(x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),name,'text/csv;charset=utf-8')}
$('entryform').onsubmit=e=>{e.preventDefault();const x=formEntry();if(!x.teacher||!x.student||!x.rule)return;if(x.override!==null&&!x.reason.trim())return toast('请填写人工调整原因');const duplicate=state.entries.some(a=>a.id!==x.id&&a.teacher===x.teacher&&a.student===x.student&&a.rule===x.rule&&a.project===x.project);if(duplicate&&!confirm('存在相同老师、学生、绩效项目和编号的记录（含其他月份），确认不是重复结算？'))return;if(editing)state.entries=state.entries.map(a=>a.id===editing?x:a);else state.entries.push(x);reset();render();if(typeof renderReview==='function')renderReview();toast('记录已保存，可在上方当月记录中核对')};
$('entryform').oninput=estimate;$('version').onchange=populate;$('teacher').onchange=()=>{if(!editing){$('version').value=state.staff[$('teacher').value.trim()]||'常规版';populate()}};$('cancel').onclick=reset;$('month').onchange=()=>{reset();render()};
function editManualEntry(id){let x=state.entries.find(x=>x.id===id);if(!x)return;editing=id;$('version').value=x.version;populate();for(let k of ['teacher','student','nature','rule','qty','ratio','project','paid','override','reason','condition','note','advisor','trialDate','enrolledCourse','fullPaid','signupHours','signupProjects'])$(k).value=x[k]??'';$('studentSignDate').value=StaffVersionPolicy.date(x.raw?.signDate||x.signDate)||'';$('formtitle').textContent='编辑补录记录';estimate();$('entries').scrollIntoView({behavior:'smooth',block:'start'})}
$('salaryrows').onchange=e=>{let n=e.target.dataset.person,k=e.target.dataset.salary;if(!k)return;let key=$('month').value+'|'+n;state.salary[key]||={base:0,allowance:0,deduct:0};state.salary[key][k]=Math.max(0,Number(e.target.value)||0);render()};
$('staffform').onsubmit=e=>{e.preventDefault();let name=$('staffname').value.trim();if(!name)return;state.staff[name]=$('staffversion').value;render();$('staffname').value='';toast('员工版本已保存')};
$('salaryExport').onclick=()=>{if(monthEntries().some(e=>calculate(e).status.startsWith('待'))&&!confirm('存在待确认记录，导出金额不包含这些记录。继续导出？'))return;csv([['月份','员工','绩效版本','基本工资','绩效金额','补贴','其他扣款','应发工资（未扣税及社保公积金）'],...salaryData().map(s=>[$('month').value,s.name,s.version,s.base,s.perf,s.allowance,s.deduct,Math.round(s.total*100)/100])],$('month').value+'工资表.csv')};
function renderRules(){const q=$('search').value.toLowerCase().replace(/top/g,'vip');$('rulelist').innerHTML=RULES.filter(r=>[r.version,r.group,r.item,r.tier].join(' ').toLowerCase().includes(q)).map(r=>`<tr><td>${esc(r.version)}</td><td class="wrap">${esc(r.group)}</td><td class="wrap">${esc(r.item)}</td><td>${esc(r.tier)}</td><td>${r.rate}元/${esc(r.unit)}</td><td class="wrap">${esc(r.note)}</td></tr>`).join('')}$('search').oninput=renderRules;
$('backup').onclick=()=>download(JSON.stringify({schema:1,...state},null,2),'绩效工具备份.json','application/json');$('restore').onchange=async e=>{try{let d=JSON.parse(await e.target.files[0].text());if(d.schema!==1||!Array.isArray(d.entries)||!d.staff||!d.salary||d.entries.some(x=>(x.rule&&!ruleBy(x.rule))||!Number.isFinite(x.qty)||x.qty<0||(!Number.isFinite(x.ratio)||x.ratio<0||x.ratio>1)||!['yes','no','pending'].includes(x.condition)||!Number.isFinite(x.paid)||x.paid<0||!(x.override===null||Number.isFinite(x.override))||typeof x.teacher!=='string'||typeof x.student!=='string'))throw Error();if(confirm('将备份恢复到本地，替换工资草稿和员工版本名单。是否继续？')){state={entries:d.entries,staff:d.staff,staffRules:d.staffRules||{},salary:d.salary};render();if(typeof renderReview==='function')renderReview();toast('备份已恢复')}}catch{toast('备份格式或记录内容无效')}e.target.value=''};
$('clear').onclick=()=>{if(confirm('清空所有月份和员工设置？请先备份。')){state={entries:[],staff:{},salary:{}};reset();render();if(typeof renderReview==='function')renderReview()}};
populate();render();renderRules();

function performanceStatusClass(status){return status==='可结算'?'':status.startsWith('排除')||status.startsWith('无绩效')?'neutral':'warn'}
